package com.coraline.secrets;
import java.util.*;
import com.coraline.feast.*;
import com.coraline.otherworld.*;
import com.mojang.authlib.GameProfile;
import net.minecraft.gametest.framework.*;
import net.minecraftforge.gametest.*;
import net.minecraftforge.common.util.FakePlayerFactory;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.core.BlockPos;
import net.minecraft.world.item.*;
import net.minecraft.world.level.block.Blocks;

@GameTestHolder("coraline") @PrefixGameTestTemplate(false)
public final class SecretsGameTests {
    static ServerPlayer fixture(GameTestHelper h){var p=FakePlayerFactory.get(h.getLevel().getServer().getLevel(OtherWorld.KEY),new GameProfile(UUID.randomUUID(),"SecretQA"));var d=new DoorData.Door();d.owner=p.getUUID();d.pos=new BlockPos(120,80,120);DoorData.get(p.server).doors.put(d.id,d);var r=RealmData.get(p.server).realm(d);r.house=r.doorPos;r.porch=r.house.south(22);r.bed=r.house.offset(11,9,-7);r.ready=true;r.islandComplete=true;
        var scene=new VisitData.Scene();scene.owner=p.getUUID();scene.door=d.id;scene.stage=VisitData.Stage.DONE;scene.table=r.house;scene.piano=r.house;scene.loop.phase=OtherMotherLoopState.Phase.EXPLORING;scene.loop.visits=1;scene.loop.secrets.visit=1;VisitData.get(p.server).scenes.put(p.getUUID(),scene);p.getPersistentData().putUUID("CoralineVisitDoor",d.id);p.setPos(r.bed.getX(),r.bed.getY(),r.bed.getZ());return p;}
    static void finishOffer(ServerPlayer p){var n=SecretTransactions.state(p).dialogue;n.remove("Queue");n.putBoolean("OfferSpoken",true);n.putBoolean("Finished",true);n.putLong("Until",0);SecretTransactions.resolveOffer(p);}
    static void warm(ServerPlayer p){var c=new net.minecraft.world.level.ChunkPos(p.blockPosition());for(int x=c.x-1;x<=c.x+1;x++)for(int z=c.z-1;z<=c.z+1;z++){p.serverLevel().setChunkForced(x,z,true);p.serverLevel().getChunk(x,z);}}
    static void cool(ServerPlayer p){var c=new net.minecraft.world.level.ChunkPos(p.blockPosition());for(int x=c.x-1;x<=c.x+1;x++)for(int z=c.z-1;z<=c.z+1;z++)p.serverLevel().setChunkForced(x,z,false);}
    @GameTest(template="empty") public static void everyAttributeLegitimatelyReachable(GameTestHelper h){h.assertTrue(SecretRegistry.ALL.size()>=30,"Too few secrets");var ids=new HashSet<String>();for(int tier=0;tier<=2;tier++){int allowed=tier;for(var s:SecretRegistry.ALL.values())if(s.tier()<=allowed)ids.add(s.id());int[] totals=SecretRegistry.totals(ids);for(int i:totals)h.assertTrue(i==(tier==0?36:tier==1?72:100),"Progression blocked");h.assertTrue(SecretRegistry.tier(totals[0])>=tier+1,"Cannot unlock next tier");}h.assertTrue(SecretRegistry.tier(32)==0&&SecretRegistry.tier(33)==1&&SecretRegistry.tier(65)==1&&SecretRegistry.tier(66)==2&&SecretRegistry.tier(99)==2&&SecretRegistry.tier(100)==3,"Threshold boundary");h.succeed();}
    @GameTest(template="empty") public static void explicitLoopsRemoveImmediately(GameTestHelper h){var s=new SecretsState();s.journal.addAll(SecretRegistry.ALL.keySet());s.recalculate();for(var loop:SecretRegistry.LOOPS.values())h.assertTrue(s.ability(loop.ability()),"Loop inactive");s.journal.remove("magical_threads");s.recalculate();h.assertFalse(s.ability("hijack"),"Hijack survived missing secret");h.assertFalse(s.ability("command"),"Overlapping loop survived");s.journal.add("magical_threads");s.recalculate();h.assertTrue(s.ability("hijack")&&s.ability("command"),"Restore failed");h.succeed();}
    @GameTest(template="empty") public static void permanentKnowledgeSeparateFromJournal(GameTestHelper h){var s=new SecretsState();s.exposed.addAll(SecretRegistry.ALL.keySet());s.journal.add("key_drawer");s.recalculate();h.assertTrue(s.value(0)==18&&s.counter(0)==1&&s.effective(0)==0,"Counter derivation");s.journal.clear();s.recalculate();h.assertTrue(s.value(0)==0&&s.counter(0)==1,"Knowledge erased");s.overrides[0]=.2;s.recalculate();h.assertTrue(s.counter(0)==.2&&s.exposed.size()==36,"Override corrupted records");s.overrides[0]=-1;h.assertTrue(s.counter(0)==1,"Natural counter lost");h.succeed();}
    @GameTest(template="empty") public static void persistenceRoundtrip(GameTestHelper h){var p=fixture(h);var s=SecretTransactions.state(p);s.journal.addAll(List.of("spying_dolls","magical_threads","servant_commands"));s.exposed.add("shadow_veil");s.hiding=4;s.inspectionProgress=.72;s.search=SecretsState.Search.INVESTIGATING_NOISE;s.target=new BlockPos(8,4,6);s.pendingTicks=731;s.seed=83763847;s.overrides[3]=.38;SecretTransactions.issue(p,"key_drawer");s.blackmail.put(UUID.randomUUID(),List.of("house_codes"));s.recalculate();var reloaded=OtherMotherLoopState.load(OtherMotherLoop.scene(p).loop.save()).secrets;h.assertTrue(reloaded.save().equals(s.save()),"Ledger failed roundtrip");h.assertTrue(reloaded.ability("hijack"),"Derived abilities not restored");h.succeed();}
    @GameTest(template="empty") public static void physicalEvidenceOwnedAndSingleUse(GameTestHelper h){var p=fixture(h);var helper=fixture(h);SecretTransactions.issue(p,"key_drawer");var evidence=p.getInventory().items.stream().filter(i->!SecretTransactions.evidence(p,i).isEmpty()).findFirst().orElseThrow();helper.getInventory().add(evidence.copy());h.assertFalse(SecretTransactions.deposit(helper,"key_drawer"),"Helper stole secret");p.getInventory().add(evidence.copy());h.assertTrue(SecretTransactions.state(p).value(0)==0,"Carrying grants stats");h.assertTrue(SecretTransactions.deposit(p,"key_drawer"),"Deposit failed");h.assertFalse(SecretTransactions.deposit(p,"key_drawer"),"Duplicate contributed");h.assertTrue(SecretTransactions.state(p).value(0)==18,"Wrong contribution");SecretTransactions.delete(p,"key_drawer");h.assertFalse(SecretTransactions.deposit(p,"key_drawer"),"Copied stale capability reusable");h.succeed();}
    @GameTest(template="empty") public static void blackmailSacrificeAndOnePayout(GameTestHelper h){var p=fixture(h);var s=SecretTransactions.state(p);s.journal.addAll(List.of("spying_dolls","magical_threads","servant_commands"));s.recalculate();h.assertTrue(SecretTransactions.makeBlackmail(p,List.copyOf(s.journal)),"Cannot sacrifice");h.assertTrue(s.journal.isEmpty()&&!s.ability("hijack"),"Ability retained");var item=p.getInventory().items.stream().filter(i->i.is(SecretsItems.BLACKMAIL.get())).findFirst().orElseThrow();var stale=item.copy();h.assertTrue(SecretTransactions.offer(p,item,1),"Acceptance failed");h.assertTrue(s.exposed.isEmpty()&&s.pendingReward==-1,"Offer resolved before speech");finishOffer(p);h.assertTrue(s.exposed.size()==3,"Source knowledge lost");SecretTransactions.reward(p,1);int count=p.getInventory().countItem(Items.DIAMOND);SecretTransactions.reward(p,1);h.assertTrue(count>0&&p.getInventory().countItem(Items.DIAMOND)==count,"Duplicate payout");h.assertFalse(SecretTransactions.offer(p,stale,1),"Reused blackmail");h.succeed();}
    @GameTest(template="empty") public static void blackmailRejectionAndInspection(GameTestHelper h){var p=fixture(h);var s=SecretTransactions.state(p);s.journal.add("soul_prisons");SecretTransactions.makeBlackmail(p,List.of("soul_prisons"));var item=p.getInventory().items.stream().filter(i->i.is(SecretsItems.BLACKMAIL.get())).findFirst().orElseThrow();SecretTransactions.offer(p,item,0);finishOffer(p);h.assertTrue(s.pendingReward==-1&&s.exposed.contains("soul_prisons"),"Rejected offer not finalized");s.journal.addAll(SecretRegistry.ALL.keySet());s.recalculate();s.hiding=3;SecretsRuntime.inspect(p,2);h.assertTrue(s.journal.size()==36,"Wrong spot discovered journal");SecretsRuntime.inspect(p,3);h.assertTrue(s.journal.isEmpty()&&s.exposed.size()==36,"Discovery did not clear/expose all");for(int i=0;i<6;i++)h.assertTrue(s.value(i)==0&&s.counter(i)==1,"Counters or stats wrong after inspection");h.succeed();}
    @GameTest(template="empty") public static void searchDelayAndNoiseStayDistinct(GameTestHelper h){var p=fixture(h);var s=SecretTransactions.state(p);var delays=new HashSet<Long>();for(int i=0;i<100;i++){MotherSearch.missed(p);h.assertTrue(s.pendingTicks>=1200&&s.pendingTicks<=12000,"Invalid delay");delays.add(s.pendingTicks);}h.assertTrue(delays.size()>80,"Delay is effectively fixed");s.pendingTicks=1;MotherSearch.tick(p);h.assertTrue(s.searching()&&SecretsRuntime.exitBlocked(p),"Search not blocking exits");float suspicion=OtherMotherLoop.scene(p).loop.suspicion;for(int i=0;i<400;i++)MotherSearch.tick(p);h.assertTrue(Math.abs(OtherMotherLoop.scene(p).loop.suspicion-suspicion-.01)<.001,"Suspicion cadence wrong");MotherSearch.bell(p);h.assertFalse(SecretsRuntime.exitBlocked(p),"Bell does not release exits");h.succeed();}
    @GameTest(template="empty") public static void inspectionCurveAndSeverity(GameTestHelper h){h.assertTrue(SecretsState.inspectionMinutes(0)==50&&SecretsState.inspectionMinutes(.5)==10&&Math.abs(SecretsState.inspectionMinutes(.99)-4)<.0001,"Inspection schedule wrong");double last=60;for(int i=0;i<=100;i++){double minutes=SecretsState.inspectionMinutes(i/100.);h.assertTrue(minutes<=last&&minutes>=4,"Nonmonotonic inspection schedule");last=minutes;}double one=SecretRegistry.severity(List.of("key_drawer")),two=SecretRegistry.severity(List.of("key_drawer","house_codes"));h.assertTrue(two>one&&two<1&&SecretRegistry.severity(List.of("key_drawer","key_drawer"))==one,"Severity duplicates");h.succeed();}
    @GameTest(template="empty",timeoutTicks=500) public static void lockAcceptsTimedInputsNotSpam(GameTestHelper h){var p=fixture(h);var s=SecretTransactions.state(p);s.journal.addAll(SecretRegistry.ALL.keySet());s.recalculate();var room=new net.minecraft.nbt.CompoundTag();var at=p.blockPosition();room.putLong("Pos",at.asLong());room.putInt("Tier",1);var rooms=new net.minecraft.nbt.ListTag();rooms.add(room);s.world.put("Rooms",rooms);p.setPos(at.getX()+.5,at.getY(),at.getZ()-6);SecretLocks.open(p,0);h.onEachTick(()->{if(s.unlocked.contains(0)){h.assertTrue(p.serverLevel().getBlockState(at.north(5)).isAir(),"Door remained closed");h.succeed();return;}try{var field=SecretLocks.class.getDeclaredField("ACTIVE");field.setAccessible(true);var attempts=(java.util.Map<?,?>)field.get(null);Object attempt=attempts.get(p.getUUID());var type=attempt.getClass();var start=type.getDeclaredMethod("start");var speed=type.getDeclaredMethod("speed");var nonce=type.getDeclaredMethod("nonce");start.setAccessible(true);speed.setAccessible(true);nonce.setAccessible(true);long elapsed=p.serverLevel().getGameTime()-(long)start.invoke(attempt);double cursor=(Math.sin(elapsed*(double)speed.invoke(attempt))+1)/2;if(Math.abs(cursor-.5)<.07)SecretLocks.pin(p,(UUID)nonce.invoke(attempt));}catch(ReflectiveOperationException ex){throw new IllegalStateException(ex);}});}
    @GameTest(template="empty") public static void spyDollNeedsContinuousLineOfSight(GameTestHelper h){var p=fixture(h);warm(p);h.runAfterDelay(20,()->{var s=SecretTransactions.state(p);var at=p.blockPosition();for(int x=-3;x<=3;x++)for(int z=-3;z<=3;z++)p.serverLevel().setBlock(at.offset(x,-1,z),Blocks.STONE.defaultBlockState(),2);var mother=com.coraline.registry.ModEntities.MOM.get().create(p.serverLevel());mother.makeOtherParent(0);mother.setNoAi(true);mother.setPos(at.getX()+12,at.getY(),at.getZ());p.serverLevel().addFreshEntity(mother);OtherMotherLoop.scene(p).mom=mother.getUUID();SecretTransactions.issue(p,"key_drawer");SecretSpies.doll(p,at.south(3));for(int i=1;i<=11;i++){p.tickCount=i*5;SecretSpies.tick(p);}h.assertTrue(s.exposed.isEmpty(),"Reported before three seconds");p.serverLevel().setBlock(at.south().above(),Blocks.STONE.defaultBlockState(),3);p.tickCount=60;SecretSpies.tick(p);p.serverLevel().setBlock(at.south().above(),Blocks.AIR.defaultBlockState(),3);for(int i=13;i<=23;i++){p.tickCount=i*5;SecretSpies.tick(p);}h.assertTrue(s.exposed.isEmpty(),"Broken sight accumulated detection");p.tickCount=120;SecretSpies.tick(p);h.assertTrue(s.exposed.contains("key_drawer"),"Continuous sight never reported");cool(p);h.succeed();});}
    @GameTest(template="empty") public static void overflowRewardsStayOwnerOnly(GameTestHelper h){var p=fixture(h);warm(p);h.runAfterDelay(20,()->{var helper=fixture(h);for(int i=0;i<36;i++)p.getInventory().setItem(i,new ItemStack(Items.COBBLESTONE,64));SecretTransactions.give(p,new ItemStack(Items.DIAMOND,3));var items=p.serverLevel().getEntitiesOfClass(net.minecraft.world.entity.item.ItemEntity.class,p.getBoundingBox().inflate(4),e->e.getItem().is(Items.DIAMOND));h.assertTrue(items.size()==1,"Overflow reward not dropped");var rejected=new net.minecraftforge.event.entity.player.EntityItemPickupEvent(helper,items.get(0));SecretsRuntime.pickup(rejected);h.assertTrue(rejected.isCanceled(),"Helper stole overflow reward");var accepted=new net.minecraftforge.event.entity.player.EntityItemPickupEvent(p,items.get(0));SecretsRuntime.pickup(accepted);h.assertFalse(accepted.isCanceled(),"Owner cannot recover overflow reward");cool(p);h.succeed();});}
    @GameTest(template="empty") public static void buildingQueueSurvivesReloadAndHonorsBudget(GameTestHelper h){var p=fixture(h);var s=SecretTransactions.state(p);var at=p.blockPosition();var queue=new net.minecraft.nbt.ListTag();for(int i=0;i<12;i++){var n=new net.minecraft.nbt.CompoundTag();n.putLong("Pos",at.offset(i,0,0).asLong());n.putString("Block","minecraft:stone");queue.add(n);}s.world.put("BuildQueue",queue);SecretWorld.drain(p,4);h.assertTrue(SecretWorld.pending(s)==8,"Placement exceeded tick budget");OtherMotherLoop.scene(p).loop.secrets=SecretsState.load(s.save());s=SecretTransactions.state(p);SecretWorld.drain(p,4);h.assertTrue(SecretWorld.pending(s)==4,"Queue cursor lost on reload");SecretWorld.drain(p,4);h.assertTrue(SecretWorld.pending(s)==0&&p.serverLevel().getBlockState(at.offset(11,0,0)).is(Blocks.STONE),"Queue failed to complete");h.succeed();}
    @GameTest(template="empty") public static void malformedCounterCannotPoisonGameplay(GameTestHelper h){var n=new SecretsState().save();n.putDouble("Override0",Double.NaN);n.putDouble("Override1",Double.POSITIVE_INFINITY);var loaded=SecretsState.load(n);h.assertTrue(loaded.counter(0)==0&&loaded.counter(1)==0,"Nonfinite override accepted");h.succeed();}
    @GameTest(template="empty") public static void rescuedSoulsWeakenPursuitWithoutErasingKnowledge(GameTestHelper h){var s=new SecretsState();s.exposed.add("quiet_steps");s.recalculate();double before=s.effective(2);s.rescued=20;h.assertTrue(s.effective(2)==before&&s.counter(2)==.18&&s.soulWeakening()==.15,"Rescue erased permanent awareness");s.journal.addAll(SecretRegistry.ALL.keySet());s.recalculate();h.assertTrue(s.effective(2)<=1&&s.effective(4)<=1,"Rescue exceeded normalized range");h.succeed();}
    @GameTest(template="empty") public static void staleEvidenceStillInvalidAfterReload(GameTestHelper h){var p=fixture(h);SecretTransactions.issue(p,"key_drawer");var item=p.getInventory().items.stream().filter(i->!SecretTransactions.evidence(p,i).isEmpty()).findFirst().orElseThrow().copy();SecretTransactions.deposit(p,"key_drawer");var scene=OtherMotherLoop.scene(p);scene.loop.secrets=SecretsState.load(scene.loop.secrets.save());SecretTransactions.delete(p,"key_drawer");p.getInventory().add(item);h.assertFalse(SecretTransactions.deposit(p,"key_drawer"),"Reload resurrected spent capability");h.succeed();}
    @GameTest(template="empty") public static void knowledgeAcquisitionDoesNotRaiseSuspicion(GameTestHelper h){var p=fixture(h);var l=OtherMotherLoop.scene(p).loop;float trust=l.trust,suspicion=l.suspicion;SecretTransactions.issue(p,"key_drawer");SecretTransactions.deposit(p,"key_drawer");SecretTransactions.delete(p,"key_drawer");h.assertTrue(l.trust==trust&&l.suspicion==suspicion,"Unobserved research changed relationship");h.succeed();}
    @GameTest(template="empty") public static void cacheAndMiningOwnerGates(GameTestHelper h){var p=fixture(h);var s=SecretTransactions.state(p);var at=p.blockPosition();var room=new net.minecraft.nbt.CompoundTag();room.putLong("Pos",at.asLong());room.putInt("Tier",2);var rooms=new net.minecraft.nbt.ListTag();rooms.add(room);s.world.put("Rooms",rooms);SecretWorld.node(s,at,"cache","cache",0);s.unlocked.add(0);SecretWorld.interact(p,at);h.assertFalse(s.claimed.contains("cache"),"Hidden cache opened below full knowledge");for(var secret:SecretRegistry.ALL.values())if(secret.points()[1]>0)s.journal.add(secret.id());s.recalculate();SecretWorld.interact(p,at);h.assertTrue(s.claimed.contains("cache"),"Cache remains inaccessible at 1.0");int count=p.getInventory().countItem(Items.DIAMOND);SecretWorld.interact(p,at);h.assertTrue(count==p.getInventory().countItem(Items.DIAMOND),"Cache duplicate");h.succeed();}
}
